static constexpr SymbolLayer get_status_layer(Status status, Affiliation affiliation, FrameShape frame_shape, bool use_alternate_icons = false) {
	struct SymbolEntry {
		SymbolLayer layer;
		IconSide icon_side = IconSide::MIDDLE;
	};

	const auto ALT_MAP = mapbox::eternal::map<Status, SymbolEntry >({
		{Status::FULLY_CAPABLE, {SymbolLayer{DrawCommand::path("M25,155 l150,0 0,25 -150,0 z", BoundingBox(25, 155, 175, 180)).with_fill(ColorType::STATUS_GREEN)}, IconSide::BOTTOM}},
		{Status::DAMAGED, {SymbolLayer{DrawCommand::path("M25,155 l150,0 0,25 -150,0 z", BoundingBox(25, 155, 175, 180)).with_fill(ColorType::STATUS_YELLOW)}, IconSide::BOTTOM}},
		{Status::DESTROYED, {SymbolLayer{DrawCommand::path("M25,155 l150,0 0,25 -150,0 z", BoundingBox(25, 155, 175, 180)).with_fill(ColorType::STATUS_RED)}, IconSide::BOTTOM}},
		{Status::FULL_TO_CAPACITY, {SymbolLayer{DrawCommand::path("M25,155 l150,0 0,25 -150,0 z", BoundingBox(25, 155, 175, 180)).with_fill(ColorType::STATUS_BLUE)}, IconSide::BOTTOM}}
	});
	const auto MAP = mapbox::eternal::map<Status, SymbolEntry>({
		{Status::PRESENT, {SymbolLayer{}, IconSide::MIDDLE}},
		{Status::PLANNED, {SymbolLayer{}, IconSide::MIDDLE}},
		{Status::FULLY_CAPABLE, {SymbolLayer{}, IconSide::MIDDLE}},
		{Status::DAMAGED, {SymbolLayer{DrawCommand::path("M150,20 L50,180", BoundingBox(50, 20, 150, 180)).with_stroke_width(8.0)}, IconSide::MIDDLE}},
		{Status::DESTROYED, {SymbolLayer{DrawCommand::path("M150,20 L50,180", BoundingBox(50, 20, 150, 180)).with_stroke_width(8.0)}, IconSide::MIDDLE}},
		{Status::FULL_TO_CAPACITY, {SymbolLayer{}, IconSide::MIDDLE}}
	});

	SymbolEntry ret;

	auto it = ALT_MAP.find(status);
	if (it != ALT_MAP.end()) {
		ret = it->second;
	} else {
		auto it = MAP.find(status);
		if (it != MAP.end()) {
			ret = it->second;
		}
	}

	if (ret.layer.empty()) {
		return {};
	}

	Vector2 offset = get_amplifier_offset(ret.icon_side, affiliation, frame_shape);
	return SymbolLayer{DrawCommand::translate(offset, ret.layer)};
}

